<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue'
import {dialogFocus as vDialogFocus} from '../dialog-focus'
import {listingSummary,label,groupRunEvents} from './matrix'
const props=defineProps<{run:any;events:any[];itemId:number|null;view:'overview'|'logs';loading:boolean;error:string;more:boolean;busy:boolean;fromHistory:boolean;canManage:boolean;resolving:boolean;notice:string}>()
const emit=defineEmits<{'update:view':[value:'overview'|'logs'];close:[];back:[];select:[id:number|null];refresh:[];copy:[];resolve:[item:any];'flash-sales':[id:number]}>()
const items=computed(()=>props.run.items||[])
const selectedItems=computed(()=>props.itemId===null?items.value:items.value.filter((item:any)=>item.id===props.itemId))
const finished=computed(()=>items.value.filter((item:any)=>['succeeded','partial_success','failed','cancelled','permission_revoked','manually_not_submitted'].includes(item.status)).length)
const groups=computed(()=>groupRunEvents(props.events))
const scopeName=computed(()=>props.itemId===null?'全部环境':items.value.find((item:any)=>item.id===props.itemId)?.environment_name||`执行项 #${props.itemId}`)
const taskName=computed(()=>['listing.catalog','promotion.flash_sale.renew','promotion.flash_sale.collect','shop.collect'].filter(task=>(props.run.tasks||[]).includes(task)).map(task=>task==='listing.catalog'?'自动上品':task==='promotion.flash_sale.renew'?'秒杀续期':task==='promotion.flash_sale.collect'?'同步秒杀活动':'店铺采集').join(' + '))
const time=(value?:string)=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Hong_Kong',hour12:false}):'—'
const environment=(id:number|null)=>id===null?'批次事件':items.value.find((item:any)=>item.id===id)?.environment_name||`执行项 #${id}`
const resolutionPanel=ref<HTMLElement|null>(null)
let resolutionTrigger:HTMLElement|null=null
watch(()=>props.resolving,async value=>{
 if(value)resolutionTrigger=document.activeElement instanceof HTMLElement?document.activeElement:null
 await nextTick()
 if(value)resolutionPanel.value?.querySelector<HTMLElement>('select,button')?.focus()
 else if(resolutionTrigger?.isConnected)resolutionTrigger.focus()
})
function tabKeys(event:KeyboardEvent){
 if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return
 event.preventDefault()
 const value=event.key==='Home'?'overview':event.key==='End'?'logs':props.view==='overview'?'logs':'overview'
 emit('update:view',value)
 ;(event.currentTarget as HTMLElement).querySelector<HTMLElement>(value==='overview'?'#run-overview-tab':'#run-logs-tab')?.focus()
}
const expanded=ref<Set<number>>(new Set()),initialized=ref(false)
watch([()=>props.run.id,()=>props.itemId],()=>{expanded.value=new Set();initialized.value=false})
watch(groups,value=>{if(!initialized.value&&value.length){expanded.value=new Set([value[value.length-1].key]);initialized.value=true}},{immediate:true})
function toggle(key:number,event:Event){const next=new Set(expanded.value);if((event.target as HTMLDetailsElement).open)next.add(key);else next.delete(key);expanded.value=next}
function steps(item:any){emit('update:view','logs');if(props.itemId!==item.id)emit('select',item.id)}
const message=(event:any)=>event?.payload?.message||label(event?.payload?.status||event?.payload?.stage||event?.kind)
</script>

<template>
<div class="modal-backdrop rv-backdrop" @click.self="!busy&&emit('close')">
<section v-dialog-focus="{close:()=>emit('close'),busy}" class="modal-card rv-dialog" role="dialog" aria-modal="true" aria-labelledby="run-viewer-title">
 <header class="rv-header">
  <div class="rv-heading"><div><span class="rv-eyebrow">运行详情 · #{{run.id}}</span><h2 id="run-viewer-title">{{taskName||'运行详情'}} <span class="rv-status" :class="run.status">{{label(run.status)}}</span></h2></div><div class="rv-header-actions"><button v-if="fromHistory&&!resolving" @click="emit('back')">← 返回运行记录</button><button :disabled="busy" @click="emit('close')">{{resolving?'返回详情':'关闭'}} <span aria-hidden="true">×</span></button></div></div>
  <dl class="rv-meta"><div><dt>计划</dt><dd>{{run.plan_name||'临时执行'}}</dd></div><div><dt>操作方案</dt><dd>{{run.operation_name||'—'}}</dd></div><div><dt>执行设备</dt><dd>{{run.device_name||(run.agent_id?`设备 #${run.agent_id}`:'—')}}</dd></div><div><dt>执行人</dt><dd>{{run.owner_name||(run.owner_id?`成员 #${run.owner_id}`:'—')}}</dd></div><div><dt>{{run.trigger==='scheduled'?'定时执行':'手动执行'}} · UTC+8</dt><dd>{{time(run.created_at)}}</dd></div></dl>
  <div class="rv-progress-row"><span>执行进度 <b>{{finished}} / {{items.length}}</b> 个环境结束</span><div class="rv-progress" role="progressbar" aria-label="环境完成进度" :aria-valuenow="finished" :aria-valuemax="items.length||1" aria-valuemin="0"><i :style="{width:`${items.length?finished/items.length*100:0}%`}"></i></div></div>
 </header>
 <div v-if="resolving" ref="resolutionPanel" class="rv-resolution"><h3>人工核对</h3><slot name="resolution"/></div>
 <div v-show="!resolving" class="rv-body">
  <aside class="rv-environments" aria-label="运行环境"><div class="rv-nav-title">执行环境 <span>{{items.length}}</span></div><button :class="{selected:itemId===null}" :aria-pressed="itemId===null" @click="emit('select',null)"><b>全部环境</b><span>{{items.length}} 个</span></button><button v-for="item in items" :key="item.id" :class="{selected:itemId===item.id}" :aria-pressed="itemId===item.id" @click="emit('select',item.id)"><b>{{item.environment_name||`环境 #${item.environment_id}`}}</b><span class="rv-dot" :class="item.status">{{label(item.status)}}</span></button></aside>
  <main class="rv-main">
   <div class="rv-content-top"><label class="rv-mobile-select">执行环境<select :value="itemId??''" @change="emit('select',($event.target as HTMLSelectElement).value?Number(($event.target as HTMLSelectElement).value):null)"><option value="">全部环境</option><option v-for="item in items" :key="item.id" :value="item.id">{{item.environment_name||`环境 #${item.environment_id}`}} · {{label(item.status)}}</option></select></label><div class="rv-tabs" role="tablist" @keydown="tabKeys" aria-label="运行内容"><button id="run-overview-tab" role="tab" :tabindex="view==='overview'?0:-1" :aria-selected="view==='overview'" aria-controls="run-overview-panel" :class="{active:view==='overview'}" @click="emit('update:view','overview')">执行概览</button><button id="run-logs-tab" role="tab" :tabindex="view==='logs'?0:-1" :aria-selected="view==='logs'" aria-controls="run-logs-panel" :class="{active:view==='logs'}" @click="emit('update:view','logs')">步骤日志 <small>{{events.length}}</small></button></div><span class="rv-scope">{{scopeName}}</span></div>
   <div v-if="error" class="rv-error" role="alert"><span>{{error}}</span><button :disabled="loading" @click="emit('refresh')">重试</button></div>
   <div class="rv-scroll" :aria-busy="loading">
    <div v-if="loading&&!items.length" class="rv-empty">正在加载运行详情…</div>
    <section v-show="view==='overview'" id="run-overview-panel" role="tabpanel" aria-labelledby="run-overview-tab" class="rv-overview">
     <article v-for="item in selectedItems" :key="item.id" class="rv-result"><div class="rv-result-title"><div><h3>{{item.environment_name||`环境 #${item.environment_id}`}}</h3><p>{{item.shop?`${item.shop.name} / ${item.shop.site} / ${item.shop.external_id||'按环境归档'}`:'当次尚未识别店铺'}}</p></div><span class="rv-status" :class="item.status">{{label(item.status)}}</span></div>
      <dl class="rv-result-fields"><div><dt>当前步骤</dt><dd>{{label(item.stage)}}</dd></div><div><dt>商品提交</dt><dd>{{label(item.submission)}}</dd></div><div><dt>数据采集</dt><dd>{{label(item.collection_status)}}</dd></div></dl>
      <div v-if="item.error" class="rv-failure"><b>异常原因</b><p>{{item.error}}</p></div><p v-if="item.result?.listing" class="rv-listing-result">平台结果：{{listingSummary(item.result.listing)}}</p>
      <p v-if="item.result?.flash_sale">秒杀续期：成功 {{item.result.flash_sale.succeeded||0}} · 失败 {{item.result.flash_sale.failed||0}} · 待核对 {{item.result.flash_sale.awaiting_attention||0}} · 跳过 {{item.result.flash_sale.skipped||0}}</p><button v-if="run.tasks?.includes('promotion.flash_sale.renew')" @click="emit('flash-sales',item.id)">查看秒杀活动明细</button>
      <footer class="rv-result-footer"><details class="rv-attempts"><summary>执行尝试 · {{item.attempts?.length||0}} 次</summary><p v-for="attempt in item.attempts" :key="attempt.id">第 {{attempt.number}} 次 · {{label(attempt.status)}} · {{time(attempt.started_at)}}</p><p v-if="!item.attempts?.length">尚未开始执行</p></details><div><button @click="steps(item)">查看步骤 →</button><button v-if="canManage&&['awaiting_attention','failed','partial_success'].includes(item.status)" class="rv-primary" :disabled="busy" @click="emit('resolve',item)">人工核对</button></div></footer>
     </article><p v-if="!selectedItems.length&&!loading&&!error" class="rv-empty">暂无执行环境</p>
    </section>
    <section v-show="view==='logs'" id="run-logs-panel" role="tabpanel" aria-labelledby="run-logs-tab" class="rv-logs">
     <div class="rv-log-toolbar"><span>{{events.length}} 条已加载日志 <small>{{loading?'正在同步…':'每 5 秒更新'}}</small></span><div><button :disabled="!events.length" @click="emit('copy')">复制日志</button><button :disabled="loading" @click="emit('refresh')">刷新</button></div></div><p v-if="notice" class="rv-copy-notice" role="status">{{notice}}</p>
     <p class="rv-log-hint">按执行顺序展示已上报步骤，历史记录未上报的细节无法补回。</p>
     <ol class="rv-timeline"><li v-for="group in groups" :key="group.key"><details :open="expanded.has(group.key)" @toggle="toggle(group.key,$event)"><summary><div class="rv-step-title"><b>{{label(group.stage)}}</b><time>{{time(group.events[0].created_at)}}</time></div><div class="rv-step-context">{{environment(group.itemId)}} · {{group.attempt?`第 ${group.attempt} 次尝试`:'批次记录'}} · {{group.events.length}} 条</div><p class="rv-step-preview">{{message(group.events[group.events.length-1])}}</p></summary><div class="rv-events"><article v-for="event in group.events" :key="event.seq"><div><time>{{time(event.created_at)}}</time><span>#{{event.seq}}</span></div><p>{{message(event)}}</p><details class="rv-json"><summary>原始数据</summary><pre>{{JSON.stringify(event.payload,null,2)}}</pre></details></article></div></details></li></ol>
     <p v-if="!groups.length" class="rv-empty">{{loading?'正在加载步骤日志…':selectedItems.some((item:any)=>item.attempts?.length)?'当前范围暂无已上报日志':'尚未开始执行，暂无步骤日志'}}</p><button v-if="more" class="rv-load-more" :disabled="loading" @click="emit('refresh')">{{loading?'加载中…':'继续加载日志'}}</button>
    </section>
   </div>
  </main>
 </div>
</section>
</div>
</template>

<style scoped>
