.rv-dialog{display:flex;flex-direction:column;width:min(1200px,calc(100vw - 32px));height:88vh;max-height:88vh;padding:0;overflow:hidden;border-radius:14px;background:#fff;color:#30374b;box-shadow:0 24px 80px #17203a30;font-size:13px;line-height:1.6}
.rv-dialog *{box-sizing:border-box}.rv-dialog button{display:inline-flex;align-items:center;justify-content:center;gap:8px;width:auto;margin:0;min-height:32px;padding:5px 11px;border:1px solid #e1e4ed;border-radius:6px;background:#fff;color:#616a7d;font:inherit;font-size:12px;cursor:pointer;flex-shrink:0}.rv-dialog button:hover{background:#f7f4ff;border-color:#c9bdef;color:#6043d4}.rv-dialog button:disabled{opacity:.5;cursor:not-allowed}.rv-dialog button:focus-visible,.rv-dialog summary:focus-visible,.rv-dialog select:focus-visible{outline:2px solid #7256e7;outline-offset:2px}.rv-dialog .rv-primary{background:#6043d4;color:#fff;border-color:#6043d4}
.rv-dialog>.rv-header{display:block;width:100%;height:auto;flex-shrink:0;padding:20px 24px 16px;border-bottom:1px solid #e8eaf1;background:linear-gradient(115deg,#fcfbff,#fff 65%)}.rv-heading,.rv-header-actions{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.rv-eyebrow{color:#8990a2;font-size:11px;letter-spacing:.4px}.rv-heading h2{display:flex;align-items:center;gap:12px;margin:3px 0 0;font-size:20px;font-weight:650}.rv-status{display:inline-flex;align-items:center;gap:5px;flex-shrink:0;padding:2px 8px;border-radius:5px;background:#f0f1f5;color:#737d8f;font-size:11px;font-weight:500;white-space:nowrap}.rv-status.failed,.rv-status.permission_revoked{background:#fff0f0;color:#c34c58}.rv-status.running{background:#eee9ff;color:#6a4bd5}.rv-status.succeeded{background:#eaf7f0;color:#26875e}.rv-status.partial_success,.rv-status.awaiting_attention{background:#fff5df;color:#a67923}
.rv-meta{display:flex;flex-wrap:wrap;gap:12px 26px;margin:16px 0}.rv-meta div{min-width:0;max-width:260px}.rv-meta dt,.rv-result-fields dt{font-size:11px;color:#9299a8}.rv-meta dd{margin:2px 0 0;font-size:12px;overflow-wrap:anywhere}.rv-progress-row{display:flex;align-items:center;gap:18px;color:#9097a6;font-size:11px}.rv-progress-row b{margin-left:6px;color:#606a7d;font-weight:500}.rv-progress{height:5px;max-width:280px;flex:1;border-radius:8px;background:#eeecf6;overflow:hidden}.rv-progress i{display:block;height:100%;background:#8063df;border-radius:8px;transition:width .3s}
.rv-body{display:flex;flex:1;min-height:0}.rv-environments{width:220px;flex-shrink:0;padding:16px 10px;overflow:auto;background:#fafbfe;border-right:1px solid #e8eaf1}.rv-nav-title{padding:0 12px 10px;font-size:11px;color:#939aab}.rv-nav-title span{margin-left:8px}.rv-environments button{display:flex;justify-content:space-between;gap:10px;width:100%;margin-bottom:4px;padding:10px 12px;text-align:left;border:1px solid transparent;background:transparent;white-space:normal}.rv-environments b{min-width:0;overflow-wrap:anywhere;font-size:12px;font-weight:500}.rv-environments button.selected{background:#eee9fc;color:#6043d4;border-color:#e5ddfa}.rv-environments button span{font-size:10px;flex-shrink:0}.rv-dot.failed{color:#c34c58}.rv-dot.succeeded{color:#26875e}.rv-dot.running{color:#6a4bd5}.rv-dot.awaiting_attention,.rv-dot.partial_success{color:#a67923}
.rv-main{display:flex;flex:1;min-width:0;flex-direction:column;overflow:hidden}.rv-content-top{display:flex;align-items:center;gap:16px;padding:0 24px;border-bottom:1px solid #e8eaf1;flex-shrink:0}.rv-tabs{display:flex;gap:22px}.rv-tabs button{padding:14px 0 12px;border:0;border-bottom:2px solid transparent;border-radius:0;background:transparent;color:#8b93a4}.rv-tabs button.active{border-bottom-color:#7050d7;color:#6043d4;font-weight:600}.rv-tabs small{padding:0 5px;border-radius:4px;background:#f0edf8;font-size:10px}.rv-scope{margin-left:auto;font-size:11px;color:#9299a8;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.rv-scroll{overflow:auto;flex:1;min-height:0;padding:20px 24px;background:#fff}.rv-mobile-select{display:none}.rv-result{padding:16px;margin-bottom:14px;border:1px solid #e5e8f0;border-radius:9px}.rv-result-title{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.rv-result-title h3{margin:0;font-size:14px;font-weight:600;overflow-wrap:anywhere}.rv-result-title p{margin:3px 0 0;color:#9299a8;font-size:11px;overflow-wrap:anywhere}.rv-result-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:16px 0}.rv-result-fields dd{margin:3px 0 0;color:#596579;font-size:12px;overflow-wrap:anywhere}.rv-failure{padding:10px 12px;border-radius:6px;background:#fff3f3;border-left:3px solid #e9a3ab;color:#b8515d;font-size:12px}.rv-failure b{font-weight:600;font-size:11px}.rv-failure p{color:inherit;margin:3px 0 0;overflow-wrap:anywhere;white-space:pre-wrap}.rv-result-footer{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-top:14px;padding-top:12px;border-top:1px solid #f0f1f5}.rv-result-footer>div{display:flex;gap:8px}.rv-attempts{color:#8790a1;font-size:11px;min-width:0}.rv-attempts summary{padding:5px 0;cursor:pointer}.rv-attempts p{margin:5px 0;overflow-wrap:anywhere}.rv-listing-result{font-size:12px;color:#6d7789}.rv-log-toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12px;color:#687387}.rv-log-toolbar small{margin-left:8px;color:#9aa2b0;font-size:10px}.rv-log-toolbar>div{display:flex;gap:8px}.rv-log-hint{margin:10px 0 18px;color:#929aaa;font-size:11px}.rv-timeline{list-style:none;margin:0;padding:0 0 0 16px}.rv-timeline>li{position:relative;padding:0 0 18px 22px;border-left:1px solid #e7e4f1}.rv-timeline>li:before{content:'';position:absolute;left:-5px;top:8px;width:9px;height:9px;border:2px solid #b5a4e8;background:#fff;border-radius:50%}.rv-timeline>li:last-child{border-left-color:transparent}.rv-timeline>li:last-child:before{background:#8063df;border-color:#8063df}.rv-timeline summary{cursor:pointer}.rv-timeline>li>details>summary{list-style:none;position:relative;padding-right:20px}.rv-timeline>li>details>summary:after{content:'+';position:absolute;right:0;top:0;color:#9a91b0}.rv-timeline>li>details[open]>summary:after{content:'−'}.rv-step-title{display:flex;gap:12px;align-items:baseline;justify-content:space-between}.rv-step-title b{font-size:13px;font-weight:600;color:#505b70}.rv-step-title time{color:#9ca3b1;font-size:10px;flex-shrink:0}.rv-step-context{font-size:10px;color:#9aa1b0;margin:3px 0}.rv-step-preview{margin:5px 0 0;color:#697589;font-size:12px;overflow-wrap:anywhere;white-space:pre-wrap}.rv-events{margin-top:10px;border-radius:7px;background:#f8f9fc;padding:0 12px}.rv-events article{padding:10px 0;border-bottom:1px solid #e9ecf3}.rv-events article:last-child{border:0}.rv-events article>div{display:flex;justify-content:space-between;color:#9aa2b2;font-size:10px}.rv-events p{margin:4px 0;font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}.rv-json{font-size:10px;color:#8993a6}.rv-json pre{max-height:260px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.7 ui-monospace,monospace;color:#66748b}.rv-empty{text-align:center;padding:50px 16px;color:#939cad;font-size:12px}.rv-error{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:12px 24px 0;padding:10px 12px;background:#fff3f3;color:#b8515d;border-radius:6px;font-size:12px;overflow-wrap:anywhere}.rv-copy-notice{color:#6043d4;font-size:11px}.rv-load-more{margin-left:38px!important}.rv-resolution{overflow:auto;padding:20px 24px}.rv-resolution h3{margin-top:0;font-size:16px}
@media(max-width:700px){.rv-backdrop{padding:8px}.rv-dialog{width:calc(100vw - 16px);height:92dvh;max-height:92dvh}.rv-header{padding:14px 16px}.rv-heading{align-items:flex-start}.rv-heading h2{font-size:17px;flex-wrap:wrap;gap:6px}.rv-header-actions{gap:6px;flex-wrap:wrap;justify-content:flex-end}.rv-header-actions button{padding:4px 8px;font-size:11px}.rv-meta{gap:8px 18px;margin:12px 0;display:grid;grid-template-columns:1fr 1fr}.rv-meta dd{font-size:11px}.rv-environments{display:none}.rv-content-top{padding:10px 16px 0;flex-wrap:wrap;gap:0}.rv-mobile-select{display:flex;align-items:center;gap:10px;width:100%;font-size:11px;color:#8791a3}.rv-mobile-select select{flex:1;min-width:0;width:auto;margin:0;padding:6px 8px;border:1px solid #e1e4ed;border-radius:6px;background:#fff;color:#566176;font:inherit}.rv-scope{display:none}.rv-scroll{padding:16px}.rv-result{padding:12px}.rv-result-footer{flex-direction:column}.rv-result-footer>div{align-self:flex-end}.rv-step-title{flex-wrap:wrap;gap:2px}.rv-log-toolbar{flex-wrap:wrap}.rv-log-toolbar small{display:block;margin:0}.rv-progress-row{gap:12px}.rv-error{margin:12px 16px 0}.rv-resolution{padding:16px}}
.rv-resolution :deep(.mx-form){display:flex;flex-direction:column;gap:16px}.rv-resolution :deep(label){display:flex;flex-direction:column;gap:7px;margin:0;font-size:12px;font-weight:500}.rv-resolution :deep(select){width:100%;margin:0;padding:9px 11px;border:1px solid #dfe2eb;border-radius:6px;background:#fff;color:#596174;font:inherit;font-size:12px}.rv-resolution :deep(p){margin:0;font-size:12px;line-height:1.7}.rv-resolution :deep(.primary){align-self:flex-end;background:#6043d4;color:#fff;border-color:#6043d4}.rv-resolution :deep(.error){color:#b8515d;margin-bottom:12px}
</style>
